public class TokenSplitterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String show(java.util.List<String> list) {
        return list == null ? "null" : list.toString();
    }

    public static void main(String[] args) {
        check("tokenize(12+34*2)", "[12, +, 34, *, 2]",
                show(TokenSplitter.tokenize("12+34*2")));
        check("tokenize(5)", "[5]", show(TokenSplitter.tokenize("5")));
        check("tokenize(empty)", "[]", show(TokenSplitter.tokenize("")));
        check("tokenize(-5+3)", "[-, 5, +, 3]", show(TokenSplitter.tokenize("-5+3")));
        check("tokenize(7/2)", "[7, /, 2]", show(TokenSplitter.tokenize("7/2")));
        check("tokenize(1+2+3)", "[1, +, 2, +, 3]", show(TokenSplitter.tokenize("1+2+3")));
        check("tokenize(100)", "[100]", show(TokenSplitter.tokenize("100")));
        check("adjacent operators", "[8, *, -, 4]", show(TokenSplitter.tokenize("8*-4")));
        check("token count", 5, TokenSplitter.tokenize("12+34*2").size());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

